UPDATE TB_EEP_MAIL_ACCOUNT_M SET ACC_NM = #{ACC_NM}, FROM_NM = #{FROM_NM}, FROM_ADDR = NULLIF(#{FROM_ADDR}, ''), REPLY_TO = NULLIF(#{REPLY_TO}, ''), BCC = NULLIF(#{BCC}, ''), CONTACT = NULLIF(#{CONTACT}, '')
	, APP_PW_ENC = #{APP_PW_ENC}
	, VERIFIED_YN = 'N', VERIFIED_DT = NULL, VERIFY_MSG = NULL
	, UPDT_EMPLY_ID = #{EMPLY_ID}
WHERE ACC_SQ = #{ACC_SQ}

