SELECT E.EMPLY_ID, E.EMPLY_NM, NULLIF(TRIM(E.EMPLY_EMAIL), '') AS EMAIL
FROM TB_EEP_EMPLY_M E
WHERE IFNULL(E.DEL_YN, 'N') = 'N' AND E.EMPLY_ID IN #{id}
